#include "ag_runtime.h"
#include "ag_flash_history_sim.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
typedef struct {unsigned begins,calls;ag_runtime_store_result_t begin_result,result;ag_history_record_t records[64];size_t count;bool commit_ambiguous;} sink_t;
static ag_runtime_store_result_t begin(void *ctx,const uint8_t sid[16]){sink_t *s=ctx;assert(sid[0]);++s->begins;return s->begin_result;}
static ag_runtime_store_result_t save(void *ctx,const ag_history_record_t *r){sink_t *s=ctx;++s->calls;if(s->result==AG_RUNTIME_STORE_OK||(s->result==AG_RUNTIME_STORE_AMBIGUOUS&&s->commit_ambiguous))s->records[s->count++]=*r;return s->result;}
static ag_can_policy_t policy(void){ag_can_policy_t p;ag_can_policy_init(&p);p.power=AG_POWER_OBD;p.ignition=AG_IGN_QUALIFIED_ON;p.hardware_validated=p.rails_valid=p.diagnostic_session_active=true;return p;}
static ag_config_t config(void){ag_config_t c={.schema_version=1,.revision=1,.dashboard_count=1,.manual_percent=50};c.dashboards[0].id=1;c.dashboards[0].widget_count=1;c.dashboards[0].widgets[0]=(ag_widget_t){1,12,{0,0,10000,10000}};return c;}
static ag_runtime_job_t job(uint32_t ecu){ag_runtime_job_t j={.job={12,{AG_CAN_ID_11,500000,ecu-8,ecu},100,50,5000}};ag_obd_capabilities_init(&j.capabilities,ecu);ag_pid_mask_set(&j.capabilities.advertised,12);return j;}
static void init(ag_runtime_t *r,sink_t *sink,size_t n){ag_runtime_job_t jobs[2]={job(0x7e8),job(0x7e9)};ag_config_t c=config();uint8_t sid[16]={1};ag_runtime_sink_t s={sink,begin,save};assert(ag_runtime_init(r,&c,jobs,n,sid,&s));assert(ag_runtime_start(r));}
static void response(ag_runtime_t *r,ag_can_policy_t *p,uint64_t now){ag_simulated_dispatch_t d;assert(ag_runtime_prepare(r,p,now));assert(ag_runtime_dispatch(r,p,now,&d));assert(d.request.length==2&&d.request.bytes[0]==1&&d.request.bytes[1]==12);ag_can_frame_t f={.id=d.profile.response_id,.length=8,.data={4,0x41,12,0x1f,0x40}};ag_scheduler_rx_result_t result=ag_runtime_receive(r,p,&f,now+1);if(result!=AG_SCHED_RX_ACCEPTED)fprintf(stderr,"RX result %d now %llu fault %d\n",result,(unsigned long long)now,r->fault);assert(result==AG_SCHED_RX_ACCEPTED);}
static void test_validation_and_session(void){ag_runtime_t r;sink_t s={0};ag_runtime_job_t j=job(0x7e8);ag_config_t c=config();uint8_t sid[16]={1};ag_runtime_sink_t sink={&s,begin,save};c.revision=0;assert(!ag_runtime_init(&r,&c,&j,1,sid,&sink));assert(s.begins==0);c=config();j.capabilities.ecu_source=0x123;assert(!ag_runtime_init(&r,&c,&j,1,sid,&sink));j=job(0x7e8);j.job.pid=13;assert(!ag_runtime_init(&r,&c,&j,1,sid,&sink));j=job(0x7e8);ag_pid_mask_set(&j.capabilities.advertised,13);c.dashboards[0].widget_count=2;c.dashboards[0].widgets[1]=(ag_widget_t){2,13,{0,0,10000,10000}};assert(!ag_runtime_init(&r,&c,&j,1,sid,&sink));c=config();memset(sid,0,16);assert(!ag_runtime_init(&r,&c,&j,1,sid,&sink));init(&r,&s,1);assert(!ag_runtime_start(&r)&&s.begins==1);s=(sink_t){.begin_result=AG_RUNTIME_STORE_BUSY};sink.context=&s;sid[0]=2;assert(ag_runtime_init(&r,&c,&j,1,sid,&sink));assert(!ag_runtime_start(&r)&&r.fault);assert(!ag_runtime_start(&r)&&s.begins==1);}
static void test_rate_quality_and_no_duplicate(void){ag_runtime_t r;sink_t s={0};init(&r,&s,1);ag_can_policy_t p=policy();response(&r,&p,0);assert(r.count==1);for(unsigned n=0;n<4;++n)assert(ag_runtime_tick(&r,&p,1));assert(r.count==1);response(&r,&p,101);assert(r.count==1&&r.rate_limited==1);response(&r,&p,1000);assert(r.count==2);assert(ag_runtime_drain(&r)&&ag_runtime_drain(&r));assert(s.count==2&&s.records[0].raw_length==2&&s.records[0].sequence==0&&s.records[1].monotonic_ms==1001);assert(ag_runtime_tick(&r,&p,6001));assert(r.count==1&&r.queue[r.head].status==AG_SAMPLE_STALE&&r.queue[r.head].raw_length==0);assert(ag_runtime_tick(&r,&p,6001)&&r.count==1);p.ignition=AG_IGN_OFF;assert(ag_runtime_tick(&r,&p,7001));assert(r.count==2&&r.queue[(r.head+1)%AG_RUNTIME_QUEUE].status==AG_SAMPLE_UNAVAILABLE);}
static void test_guard_recheck_timeout_fc(void){ag_runtime_t r;sink_t s={0};init(&r,&s,1);ag_can_policy_t p=policy();ag_simulated_dispatch_t d;
    for(unsigned n=0;n<5;++n){p=policy();assert(ag_runtime_prepare(&r,&p,n));if(n==0)p.power=AG_POWER_USB_ONLY;else if(n==1)p.ignition=AG_IGN_UNKNOWN;else if(n==2)p.ignition=AG_IGN_OFF;else if(n==3)p.standby_requested=true;else p.hardware_validated=false;assert(!ag_runtime_dispatch(&r,&p,n,&d)&&d.request.length==0);}
    p=policy();assert(ag_runtime_prepare(&r,&p,10)&&ag_runtime_dispatch(&r,&p,10,&d));ag_can_frame_t ff={.id=0x7e8,.length=8,.data={0x10,8,0x41,12,0,0,0,0}};assert(ag_runtime_receive(&r,&p,&ff,11)==AG_SCHED_RX_WAITING);assert(ag_runtime_fc_prepare(&r,&p,11));p.ignition=AG_IGN_UNKNOWN;ag_can_frame_t fc;assert(!ag_runtime_fc_dispatch(&r,&p,12,&fc)&&fc.length==0);
    p=policy();assert(ag_runtime_prepare(&r,&p,110)&&ag_runtime_dispatch(&r,&p,110,&d));assert(ag_runtime_tick(&r,&p,160));assert(r.scheduler.jobs[0].sample.status==AG_SAMPLE_TIMEOUT);assert(r.count==1&&r.queue[r.head].status==AG_SAMPLE_TIMEOUT);assert(ag_runtime_tick(&r,&p,160)&&r.count==1);assert(!ag_runtime_tick(&r,&p,159)&&r.fault);assert(!ag_runtime_prepare(&r,&p,200));}
static void test_distinct_ecu_and_backpressure(void){ag_runtime_t r;sink_t s={0};init(&r,&s,2);ag_can_policy_t p=policy();response(&r,&p,0);response(&r,&p,2);assert(r.count==1&&r.rate_limited==1);assert(r.scheduler.jobs[0].sample.status==AG_SAMPLE_VALID&&r.scheduler.jobs[1].sample.status==AG_SAMPLE_VALID);assert(r.scheduler.jobs[0].sample.ecu_source!=r.scheduler.jobs[1].sample.ecu_source);
    init(&r,&s,1);for(unsigned n=0;n<17;++n)response(&r,&p,1000*n);assert(r.count==16&&r.producer_dropped==1);s.result=AG_RUNTIME_STORE_BUSY;assert(!ag_runtime_drain(&r)&&r.count==16&&!r.fault);s.result=AG_RUNTIME_STORE_OK;assert(ag_runtime_drain(&r)&&r.count==15&&r.persisted==1);assert(s.records[0].monotonic_ms==1);}
static void test_ambiguous_and_counter_bounds(void){ag_runtime_t r;sink_t s={0};init(&r,&s,1);ag_can_policy_t p=policy();response(&r,&p,0);s.result=AG_RUNTIME_STORE_AMBIGUOUS;s.commit_ambiguous=true;assert(!ag_runtime_drain(&r)&&r.fault&&r.storage_ambiguous&&r.count==1);assert(!ag_runtime_drain(&r)&&s.calls==1&&s.count==1);ag_simulated_dispatch_t d;assert(!ag_runtime_dispatch(&r,&p,1001,&d)&&d.request.length==0);
    s=(sink_t){0};init(&r,&s,1);r.persisted=UINT64_MAX;response(&r,&p,0);assert(!ag_runtime_drain(&r)&&r.fault&&s.calls==0);assert(!ag_runtime_drain(&r)&&s.calls==0);
    s=(sink_t){0};init(&r,&s,1);for(unsigned n=0;n<16;++n)response(&r,&p,n*1000);r.producer_dropped=UINT64_MAX;assert(ag_runtime_prepare(&r,&p,16000)&&ag_runtime_dispatch(&r,&p,16000,&d));ag_can_frame_t f={.id=0x7e8,.length=8,.data={4,0x41,12,0,0}};assert(ag_runtime_receive(&r,&p,&f,16001)==AG_SCHED_RX_BLOCKED);assert(r.fault&&r.producer_dropped==UINT64_MAX);}
static void test_real_simulated_journal_and_reboot(void){uint8_t bytes[8192];ag_flash_history_sim_t sim;assert(ag_flash_history_sim_init(&sim,bytes,sizeof(bytes)));ag_flash_history_io_t base=ag_flash_history_sim_io(&sim);ag_journal_io_t io={base.context,base.read,base.program,base.erase_sector};ag_journal_history_t journal;assert(ag_journal_open(&journal,&io,2)==AG_JOURNAL_EMPTY);uint8_t sid[16]={3};assert(ag_journal_bootstrap(&journal,sid,1,1)==AG_JOURNAL_OK);ag_runtime_t r;ag_config_t c=config();ag_runtime_job_t j=job(0x7e8);ag_runtime_sink_t sink={&journal,ag_runtime_journal_begin,ag_runtime_journal_append};sid[0]=4;assert(ag_runtime_init(&r,&c,&j,1,sid,&sink)&&ag_runtime_start(&r));ag_can_policy_t p=policy();response(&r,&p,0);assert(ag_runtime_drain(&r));ag_history_snapshot_t snap;assert(ag_journal_window(&journal,sid,0,&snap)==AG_JOURNAL_OK&&snap.count==1&&snap.records[0].sequence==1);ag_flash_history_sim_reboot(&sim);assert(ag_journal_open(&journal,&io,2)==AG_JOURNAL_OK);sid[0]=5;assert(ag_runtime_init(&r,&c,&j,1,sid,&sink)&&ag_runtime_start(&r));response(&r,&p,0);assert(ag_runtime_drain(&r));sid[0]=4;assert(ag_journal_window(&journal,sid,0,&snap)==AG_JOURNAL_OK&&snap.count==1);sid[0]=5;assert(ag_journal_window(&journal,sid,0,&snap)==AG_JOURNAL_OK&&snap.records[0].monotonic_ms==1);}
int main(void){test_validation_and_session();test_rate_quality_and_no_duplicate();test_guard_recheck_timeout_fc();test_distinct_ecu_and_backpressure();test_ambiguous_and_counter_bounds();test_real_simulated_journal_and_reboot();printf("PASS: 6 runtime groups; metadata %zu bytes; simulated handoffs only\n",sizeof(ag_runtime_t));return 0;}
